  LinearLayout extras=col();String[] repeats={"none","daily","weekly","monthly","yearly"};Spinner repeat=new Spinner(this);repeat.setAdapter(new ArrayAdapter<>(this,android.R.layout.simple_spinner_dropdown_item,new String[]{"No repetir","Cada día","Cada semana","Cada mes","Cada año"}));for(int n=0;n<repeats.length;n++)if(repeats[n].equals(i.optString("repeat","none")))repeat.setSelection(n);field(extras,"REPETICIÓN",repeat);
  int[] minutes={-1,0,10,30,60,1440};Spinner reminder=new Spinner(this);reminder.setAdapter(new ArrayAdapter<>(this,android.R.layout.simple_spinner_dropdown_item,new String[]{"Sin recordatorio","A la hora de la actividad","10 minutos antes","30 minutos antes","1 hora antes","1 día antes"}));for(int n=0;n<minutes.length;n++)if(minutes[n]==i.optInt("remind",-1))reminder.setSelection(n);field(extras,"RECORDATORIO",reminder);add(extras,text("Los avisos necesitan una hora y permiso de notificaciones. Activa Avisos exactos para recibirlos con la pantalla apagada. Al repetir, se conserva cada ocurrencia y se prepara la siguiente.",12,MUTED,false),12);extras.setVisibility(i.optInt("remind",-1)>=0||!i.optString("repeat","none").equals("none")?View.VISIBLE:View.GONE);add(form,button("↻  Repetición y recordatorios",false,()->extras.setVisibility(extras.getVisibility()==View.VISIBLE?View.GONE:View.VISIBLE)),10);add(form,extras,8);
