  if(!Alerts.exact(this)){new AlertDialog.Builder(this).setTitle("La prueba necesita avisos exactos").setMessage("Activa el permiso para que la prueba llegue en un minuto. Sin él, Android puede aplazarla.").setPositiveButton("Activar permiso",(d,w)->openExactSettings()).setNegativeButton("Cancelar",null).show();return;}
